package server

// Source-owned additions to the historical spreadsheet catalog. Keep these
// outside its generated file so rebuilding that file cannot erase live codes.
// When a code enters the spreadsheet, remove its extension in the same change.
func init() {
	for _, entry := range []CatalogEntry{
		// Stage 49.4.4 shared request envelope (internal/server/request_envelope.go).
		// Client errors with no business content, so none is logged: an attacker
		// probing the limits must not be able to flood system_error_logs.
		{Code: "GLOBAL-0303", MessageID: "EXT-GLOBAL-0303", Module: "Global", Scenario: "Request method not allowed", MessageType: "Error", UserMessage: "This request method is not supported here.", UserAction: "Use GET to read and POST, PUT or DELETE to change data, as the API documentation shows.", Severity: "Low", Blocking: true, DisplayStyle: "Toast", HTTPStatus: 405, Priority: "P3", RequirementLevel: "Mature ERP"},
		{Code: "GLOBAL-0304", MessageID: "EXT-GLOBAL-0304", Module: "Global", Scenario: "Request content type or encoding not accepted", MessageType: "Error", UserMessage: "The request body is in a format this address does not accept.", UserAction: "Send JSON (Content-Type: application/json), or a file upload as multipart/form-data, without compression.", Severity: "Low", Blocking: true, DisplayStyle: "Toast", HTTPStatus: 415, Priority: "P3", RequirementLevel: "Mature ERP"},
		{Code: "GLOBAL-0305", MessageID: "EXT-GLOBAL-0305", Module: "Global", Scenario: "Request body too large", MessageType: "Error", UserMessage: "The request is too large to accept.", UserAction: "Send less data at once - split a large file or list into smaller parts.", Severity: "Low", Blocking: true, DisplayStyle: "Page banner", HTTPStatus: 413, Priority: "P3", RequirementLevel: "Mature ERP"},
		{Code: "GLOBAL-0306", MessageID: "EXT-GLOBAL-0306", Module: "Global", Scenario: "Request headers too large", MessageType: "Error", UserMessage: "The request carries too many or too large headers.", UserAction: "Sign out and back in; if this persists, contact support - a browser extension or proxy may be adding headers.", Severity: "Low", Blocking: true, DisplayStyle: "Toast", HTTPStatus: 431, Priority: "P3", RequirementLevel: "Mature ERP"},
		{Code: "GLOBAL-0307", MessageID: "EXT-GLOBAL-0307", Module: "Global", Scenario: "Malformed, ambiguous or over-nested JSON request", MessageType: "Error", UserMessage: "The request data could not be accepted.", UserAction: "Check the request is one valid JSON value, with no field repeated in the same object.", Severity: "Low", Blocking: true, DisplayStyle: "Toast", HTTPStatus: 400, Priority: "P3", RequirementLevel: "Mature ERP"},
		{Code: "GLOBAL-0308", MessageID: "EXT-GLOBAL-0308", Module: "Global", Scenario: "Request exceeded its time limit", MessageType: "Error", UserMessage: "This took longer than the time a single request is allowed, so it was stopped.", UserAction: "Send less at once - split a large import file into smaller files, or narrow a report's filters and use background export.", Severity: "Medium", Blocking: true, DisplayStyle: "Page banner", HTTPStatus: 504, LogRequired: true, Priority: "P2", RequirementLevel: "Mature ERP"},
		{Code: "GOODSR-0096", MessageID: "EXT-GOODSR-0096", Module: "Goods Receipt", Scenario: "Damaged quantity requires a reason", MessageType: "Error", UserMessage: "Enter a damage reason for each damaged receipt line.", UserAction: "Record the observed damage and submit the receipt again.", Severity: "High", Blocking: true, DisplayStyle: "Field inline", HTTPStatus: 422, LogRequired: true, Priority: "P1", RequirementLevel: "Mature ERP"},
		{Code: "GOODSR-0097", MessageID: "EXT-GOODSR-0097", Module: "Goods Receipt", Scenario: "Rejected and damaged quantities exceed received quantity", MessageType: "Error", UserMessage: "Rejected plus damaged quantity cannot exceed received quantity.", UserAction: "Check the received, rejected and damaged counts; correct the line before submitting.", Severity: "High", Blocking: true, DisplayStyle: "Field inline", HTTPStatus: 422, LogRequired: true, Priority: "P1", RequirementLevel: "Mature ERP"},
		{Code: "DATAIM-0189", MessageID: "EXT-DATAIM-0189", Module: "Data Import / Excel Upload", Scenario: "Uploaded file exceeds the maximum import row count", MessageType: "Error", UserMessage: "This file has too many rows to import in one go.", UserAction: "Split the file into smaller batches and import them one at a time.", Severity: "Medium", Blocking: true, DisplayStyle: "Page banner", HTTPStatus: 422, LogRequired: true, Priority: "P2", RequirementLevel: "Mature ERP"},
		{Code: "ASSET-0273", MessageID: "EXT-ASSET-0273", Module: "Fixed Assets", Scenario: "A Fixed Asset item was put on a sale, order or invoice", MessageType: "Error", UserMessage: "This item is a fixed asset, not stock for sale, so it cannot be sold, ordered or invoiced.", UserAction: "Remove it from the sale. Fixed assets are managed under HRM -> Fixed Assets.", Severity: "High", Blocking: true, DisplayStyle: "Page banner", HTTPStatus: 422, LogRequired: true, Priority: "P1", RequirementLevel: "Mature ERP"},
		{Code: "POSOFF-0245", MessageID: "EXT-POSOFF-0245", Module: "POS / Billing", Scenario: "POS session or sale attempted at a location that is not a selling location", MessageType: "Error", UserMessage: "This location is not a selling location, so a till cannot sell from it.", UserAction: "Choose the store you are selling from, or ask an administrator to set Sellable = Yes on this Location.", Severity: "High", Blocking: true, DisplayStyle: "Page banner", HTTPStatus: 422, LogRequired: true, Priority: "P1", RequirementLevel: "Mature ERP"},
		// Stage 60.1/60.2 number series and store identity (engines/number_series.go,
		// engines/master_data_validation.go validateLocationIdentityCodes).
		{Code: "ADMINC-0310", MessageID: "EXT-ADMINC-0310", Module: "Admin / Configuration", Scenario: "Number series prefix already used by another series", MessageType: "Error", UserMessage: "This prefix is already used by another number series.", UserAction: "Choose a prefix no other transaction uses - two series with one prefix could print the same number.", Severity: "High", Blocking: true, DisplayStyle: "Field inline", HTTPStatus: 422, Priority: "P1", RequirementLevel: "Mature ERP"},
		{Code: "ADMINC-0311", MessageID: "EXT-ADMINC-0311", Module: "Admin / Configuration", Scenario: "Number series settings invalid", MessageType: "Error", UserMessage: "The number series settings are not valid.", UserAction: "Use letters, digits, '-', '_' or '.' in prefix and suffix (no spaces, up to 20), a separator of up to 3 characters and a length of 1 to 12 digits.", Severity: "Medium", Blocking: true, DisplayStyle: "Field inline", HTTPStatus: 422, Priority: "P2", RequirementLevel: "Mature ERP"},
		{Code: "MASTER-0312", MessageID: "EXT-MASTER-0312", Module: "Master Data", Scenario: "Store Short Code already used by another store", MessageType: "Error", UserMessage: "Another store already uses this Short Code.", UserAction: "Give each store its own Short Code - it is printed inside document numbers.", Severity: "High", Blocking: true, DisplayStyle: "Field inline", HTTPStatus: 422, Priority: "P1", RequirementLevel: "Mature ERP"},
		{Code: "MASTER-0313", MessageID: "EXT-MASTER-0313", Module: "Master Data", Scenario: "Store Facility Code already used by another store", MessageType: "Error", UserMessage: "Another store already uses this Facility Code.", UserAction: "Give each store its own Facility Code - OMS orders find their store by it.", Severity: "High", Blocking: true, DisplayStyle: "Field inline", HTTPStatus: 422, Priority: "P1", RequirementLevel: "Mature ERP"},
		// Stage 60.6 platform data console (engines/platform_console.go).
		{Code: "PLATFORM-0316", MessageID: "EXT-PLATFORM-0316", Module: "Admin / Configuration", Scenario: "Data console edit refused for a protected table or column", MessageType: "Error", UserMessage: "This value cannot be changed from the data console.", UserAction: "Keys, hidden (secret or personal) values and audit tables are protected. Change the record through its own screen instead.", Severity: "Medium", Blocking: true, DisplayStyle: "Page banner", HTTPStatus: 422, LogRequired: true, Priority: "P2", RequirementLevel: "Mature ERP"},
		{Code: "PLATFORM-0317", MessageID: "EXT-PLATFORM-0317", Module: "Admin / Configuration", Scenario: "Cross-client action (data console, client list, plans, sandboxes) by someone who is not a platform operator", MessageType: "Error", UserMessage: "Only a platform operator can see or change other clients.", UserAction: "Ask the server administrator to add your client and username to ERP_PLATFORM_OPERATORS.", Severity: "High", Blocking: true, DisplayStyle: "Page banner", HTTPStatus: 403, LogRequired: true, Priority: "P1", RequirementLevel: "Mature ERP"},
		// Stage 62 multi-PO GRN at invoice price (engines/grn_pricing.go).
		{Code: "GOODSR-0318", MessageID: "EXT-GOODSR-0318", Module: "Goods Receipt", Scenario: "One goods receipt given POs of different vendors", MessageType: "Error", UserMessage: "A goods receipt can only take purchase orders of the same vendor.", UserAction: "Remove the PO of the other vendor and receive it on its own goods receipt.", Severity: "High", Blocking: true, DisplayStyle: "Field inline", HTTPStatus: 422, Priority: "P1", RequirementLevel: "Mature ERP"},
		{Code: "GOODSR-0319", MessageID: "EXT-GOODSR-0319", Module: "Goods Receipt", Scenario: "Invoice rate on a receipt line is negative", MessageType: "Error", UserMessage: "The invoice rate cannot be negative.", UserAction: "Enter the per-unit price before GST exactly as the vendor's invoice shows it, or leave it blank to use the PO price.", Severity: "Medium", Blocking: true, DisplayStyle: "Field inline", HTTPStatus: 422, Priority: "P2", RequirementLevel: "Mature ERP"},
		// Stage 65.4 product attributes extended from the PO (engines/item_names.go).
		{Code: "PIM-0321", MessageID: "EXT-PIM-0321", Module: "PIM", Scenario: "Adding an attribute value from the PO that cannot be added", MessageType: "Error", UserMessage: "That value could not be added to the product attribute.", UserAction: "Type one value without commas, for an attribute chosen from a list; typed attributes take their value on the design itself.", Severity: "Low", Blocking: true, DisplayStyle: "Field inline", HTTPStatus: 422, Priority: "P3", RequirementLevel: "Mature ERP"},
		// Stage 65.2 PO delete (internal/server/handlers_core_doc_engine.go).
		{Code: "PURCHA-0320", MessageID: "EXT-PURCHA-0320", Module: "Purchase Order", Scenario: "Deleting a purchase order that goods have been received against", MessageType: "Error", UserMessage: "This purchase order cannot be deleted - goods have already been received against it.", UserAction: "Cancel the goods receipt first (or return the goods with a Purchase Return); the purchase order can then be deleted.", Severity: "Medium", Blocking: true, DisplayStyle: "Page banner", HTTPStatus: 422, Priority: "P2", RequirementLevel: "Mature ERP"},
		// Stage 60.4 item type behaviour (engines/item_types.go).
		{Code: "POSOFF-0314", MessageID: "EXT-POSOFF-0314", Module: "POS / Billing", Scenario: "Free-with-item product billed without its parent item", MessageType: "Error", UserMessage: "This item is free only with its parent item, which is not on the bill in the same quantity.", UserAction: "Add the parent item to the bill, or remove the free item.", Severity: "Medium", Blocking: true, DisplayStyle: "Page banner", HTTPStatus: 422, Priority: "P2", RequirementLevel: "Mature ERP"},
		{Code: "MASTER-0315", MessageID: "EXT-MASTER-0315", Module: "Master Data", Scenario: "Free-with-item product has no parent item", MessageType: "Error", UserMessage: "Choose the item this one is given free with.", UserAction: "Set \"Free with item\" to the main product - it cannot be the item itself.", Severity: "Medium", Blocking: true, DisplayStyle: "Field inline", HTTPStatus: 422, Priority: "P2", RequirementLevel: "Mature ERP"},
	} {
		if _, exists := errorCatalog[entry.Code]; exists {
			panic("duplicate error catalog extension: " + entry.Code)
		}
		errorCatalog[entry.Code] = entry
	}
}
